#!/usr/bin/env node

// src/core/lock.ts
import {
  open,
  unlink,
  rename,
  writeFile as _writeFile,
  copyFile,
  chmod
} from "fs/promises";
async function withFileLock(targetPath, fn) {
  const lockPath = `${targetPath}.lock`;
  let fd;
  try {
    fd = await open(lockPath, "wx");
  } catch (err) {
    if (err.code === "EEXIST") {
      throw new Error(
        `Another gram process is writing ${targetPath}. Retry in a moment.`
      );
    }
    throw err;
  }
  try {
    return await fn();
  } finally {
    await fd.close();
    await unlink(lockPath).catch(() => {
    });
  }
}
async function atomicWrite(targetPath, content, mode) {
  const tmp = `${targetPath}.tmp`;
  await _writeFile(
    tmp,
    content,
    mode !== void 0 ? { encoding: "utf-8", mode } : "utf-8"
  );
  try {
    await rename(tmp, targetPath);
  } catch (err) {
    if (err.code === "EEXIST") {
      await copyFile(tmp, targetPath);
      await unlink(tmp).catch(() => {
      });
    } else {
      throw err;
    }
  }
  if (mode !== void 0) {
    await chmod(targetPath, mode).catch(() => {
    });
  }
}

export {
  withFileLock,
  atomicWrite
};
